interface Node { render(): string }
class Leaf implements Node { constructor(public name: string) {}
  render() { return this.name }
}
class Branch implements Node {
  children: Node[] = []
  add(child: Node) { this.children.push(child) }
  render() { return this.children.map(c => c.render()).join(',') }
}
function addToIfBranch(node: Node, child: Node) {
  if ((node as Branch).add) { (node as Branch).add(child) }
}

